import re, os, sys, time, urllib.request, collections

BASE = "http://house-of-hollow-houses.chal.csaw.io:8000"
OUT = "/home/ctfplayer/workspace/pages"
os.makedirs(OUT, exist_ok=True)

seen = set()
queue = collections.deque(["/"])
pages = {}
while queue:
    path = queue.popleft()
    if path in seen:
        continue
    seen.add(path)
    url = BASE + path
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data = r.read().decode("utf-8", "replace")
    except Exception as e:
        print("ERR", path, e)
        continue
    pages[path] = data
    fn = os.path.join(OUT, (path.strip("/") or "INDEX").replace("/", "_") + ".html")
    open(fn, "w").write(data)
    # collect hrefs
    for m in re.finditer(r'''href=["']([^"'#?]+)''', data):
        h = m.group(1)
        if h.startswith("http"):
            if not h.startswith(BASE):
                continue
            h = h[len(BASE):]
        if h.startswith("/") and not h.startswith("//"):
            pass
        elif not h.startswith("/"):
            # relative
            d = path if path.endswith("/") else path + "/"
            h = os.path.normpath(os.path.join(d, h))
            if not h.startswith("/"):
                h += "/"
        if h.endswith((".css", ".js", ".png", ".ico", ".svg")):
            continue
        if not h.endswith("/"):
            h = h + "/"
        if h not in seen:
            queue.append(h)

print("pages:", len(pages), "paths requested:", len(seen))
for p in sorted(pages):
    print(p, len(pages[p]))

